def serialize(root, val, left, right):
    out = []
    queue = [root]
    for u in queue:  # the list grows while we walk it
        if u == -1:
            out.append(-1)
        else:
            out.append(val[u])
            queue.append(left[u])
            queue.append(right[u])
    while out and out[-1] == -1:
        out.pop()
    return out


def bstFromPreorder(preorder):
    n = len(preorder)
    left, right = [-1] * n, [-1] * n   # node i is preorder[i]
    stack = [0]
    for i in range(1, n):
        v = preorder[i]
        last = -1
        while stack and preorder[stack[-1]] < v:
            last = stack.pop()
        if last != -1:
            right[last] = i
        else:
            left[stack[-1]] = i
        stack.append(i)
    return serialize(0, preorder, left, right)
